1	/**
2	 * Stripe Billing adapter. One probe = a fresh billing world on its own test clock (product,
3	 * prices, coupons, customer, subscription), then one `create_preview` of the probed change. The
4	 * same code runs against Stripe test mode and against the clone: only the SDK's host changes.
5	 */
6	import { existsSync, readFileSync } from "node:fs";
7	import { join } from "node:path";
8	import Stripe from "stripe";
9	import { z } from "zod";
10	import type { Probe, Side, TargetAdapter } from "../../harness/src/adapter.ts";
11	import { JsonSchema, type Json } from "../../harness/src/json.ts";
12	import { startClone } from "./clone/server.ts";
13	import { probes } from "./probes.ts";
14	import { LifeInput, runLifecycle } from "./lifecycle.ts";
15	import { ExploreInput, runExplore } from "./explore.ts";
16	import { runWalkthrough, UiInput } from "./ui.ts";
17	import { runWide, WideInput } from "./wide.ts";
18	
19	const Coupon = z.object({
20	  percent_off: z.number().optional(),
21	  amount_off: z.number().optional(),
22	  duration: z.enum(["forever", "once"]),
23	});
24	const Plan = z.object({ amount: z.number(), interval: z.enum(["month", "year"]) });
25	const Input = z.object({
26	  start: z.number(),
27	  billing_mode: z.enum(["flexible", "classic"]),
28	  plan: Plan,
29	  quantity: z.number(),
30	  coupon: Coupon.nullable(),
31	  change: z.object({
32	    plan: Plan.nullable(),
33	    quantity: z.number().nullable(),
34	    offset: z.number(),
35	    proration_behavior: z.enum(["create_prorations", "none", "always_invoice"]).nullable(),
36	    discount: Coupon.nullable(),
37	  }),
38	});
39	
40	// The key comes from STRIPE_SECRET_KEY, else from the file named by STRIPE_ENV, else from .env at
41	// the repository root (git-ignored).
42	function testKey(): string {
43	  const file = process.env.STRIPE_ENV ?? join(import.meta.dirname, "..", "..", ".env");
44	  const fromFile = existsSync(file)
45	    ? /STRIPE_SECRET_KEY=(\S+)/.exec(readFileSync(file, "utf8"))?.[1]
46	    : undefined;
47	  const key = process.env.STRIPE_SECRET_KEY ?? fromFile;
48	  // Invariant 4: never record outside test mode.
49	  if (key?.startsWith("sk_test_") !== true) {
50	    throw new Error("refusing: STRIPE_SECRET_KEY is missing or not a test key (see .env.example)");
51	  }
52	  return key;
53	}
54	
55	function client(side: Side): Stripe {
56	  if (side.kind === "target") return new Stripe(testKey(), { maxNetworkRetries: 2 });
57	  const url = new URL(side.url);
58	  return new Stripe("sk_test_clone", {
59	    host: url.hostname,
60	    port: Number(url.port),
61	    protocol: "http",
62	  });
63	}
64	
65	const toJson = (v: unknown): Json => JsonSchema.parse(JSON.parse(JSON.stringify(v)));
66	
67	function errorJson(e: unknown): Json {
68	  if (e instanceof Stripe.errors.StripeError) {
69	    return {
70	      error: { type: e.type, code: e.code ?? null, param: e.param ?? null, message: e.message },
71	    };
72	  }
73	  throw e;
74	}
75	
76	async function couponId(stripe: Stripe, c: z.infer<typeof Coupon>): Promise<string> {
77	  const created = await stripe.coupons.create({
78	    duration: c.duration,
79	    ...(c.percent_off !== undefined ? { percent_off: c.percent_off } : {}),
80	    ...(c.amount_off !== undefined ? { amount_off: c.amount_off, currency: "usd" } : {}),
81	  });
82	  return created.id;
83	}
84	
85	async function run(probe: Probe, side: Side): Promise<Record<string, Json>> {
86	  const ui = UiInput.safeParse(probe.input);
87	  if (ui.success) return runWalkthrough(client(side), ui.data);
88	  const explore = ExploreInput.safeParse(probe.input);
89	  if (explore.success) return runExplore(client(side), explore.data);
90	  const wide = WideInput.safeParse(probe.input);
91	  if (wide.success) return runWide(client(side), wide.data, toJson, errorJson);
92	  const life = LifeInput.safeParse(probe.input);
93	  if (life.success) return runLifecycle(client(side), life.data);
94	  const p = Input.parse(probe.input);
95	  const stripe = client(side);
96	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: p.start });
97	  const price = async (plan: z.infer<typeof Plan>, name: string): Promise<string> => {
98	    const product = await stripe.products.create({ name });
