1	/**
2	 * The widened slice-1 probe: the same mid-cycle change previewed with `create_preview`, on a
3	 * subscription of one to three items sharing a monthly or yearly interval, with up to two
4	 * coupons. The original single-item probe is the special case of one item and at most one coupon;
5	 * it keeps its own input shape so that its recorded fixtures stay valid.
6	 */
7	import type Stripe from "stripe";
8	import { z } from "zod";
9	import type { Json } from "../../harness/src/json.ts";
10	
11	export const Coupon = z.object({
12	  percent_off: z.number().optional(),
13	  amount_off: z.number().optional(),
14	  duration: z.enum(["forever", "once"]),
15	});
16	export type Coupon = z.infer<typeof Coupon>;
17	
18	const Interval = z.enum(["month", "year"]);
19	
20	export const WideInput = z.object({
21	  kind: z.literal("wide"),
22	  start: z.number(),
23	  billing_mode: z.enum(["flexible", "classic"]),
24	  interval: Interval,
25	  items: z
26	    .array(z.object({ amount: z.number(), quantity: z.number() }))
27	    .min(1)
28	    .max(3),
29	  coupons: z.array(Coupon).max(2),
30	  change: z.object({
31	    item: z.number().int().min(0),
32	    amount: z.number().nullable(),
33	    // Only with a single item: a subscription's items share one interval.
34	    interval: Interval.nullable(),
35	    quantity: z.number().nullable(),
36	    offset: z.number(),
37	    proration_behavior: z.enum(["create_prorations", "none", "always_invoice"]).nullable(),
38	    discount: Coupon.nullable(),
39	  }),
40	});
41	export type WideInput = z.infer<typeof WideInput>;
42	
43	export async function couponId(stripe: Stripe, c: Coupon): Promise<string> {
44	  const created = await stripe.coupons.create({
45	    duration: c.duration,
46	    ...(c.percent_off !== undefined ? { percent_off: c.percent_off } : {}),
47	    ...(c.amount_off !== undefined ? { amount_off: c.amount_off, currency: "usd" } : {}),
48	  });
49	  return created.id;
50	}
51	
52	export async function runWide(
53	  stripe: Stripe,
54	  p: WideInput,
55	  toJson: (v: unknown) => Json,
56	  errorJson: (e: unknown) => Json,
57	): Promise<Record<string, Json>> {
58	  const clock = await stripe.testHelpers.testClocks.create({ frozen_time: p.start });
59	  const price = async (amount: number, interval: "month" | "year", name: string) => {
60	    const product = await stripe.products.create({ name });
61	    const created = await stripe.prices.create({
62	      product: product.id,
63	      currency: "usd",
64	      unit_amount: amount,
65	      recurring: { interval },
66	    });
67	    return created.id;
68	  };
69	  const names = ["Plan A", "Plan B", "Plan C"];
70	  const prices: string[] = [];
71	  for (const [i, item] of p.items.entries())
72	    prices.push(await price(item.amount, p.interval, names[i] ?? "Plan"));
73	  const changed = p.items[p.change.item];
74	  if (!changed) throw new Error(`change.item ${String(p.change.item)} is out of range`);
75	  const newPrice =
76	    p.change.amount !== null || p.change.interval !== null
77	      ? await price(p.change.amount ?? changed.amount, p.change.interval ?? p.interval, "Plan New")
78	      : null;
79	  const customer = await stripe.customers.create({
80	    test_clock: clock.id,
81	    payment_method: "pm_card_visa",
82	    invoice_settings: { default_payment_method: "pm_card_visa" },
83	    preferred_locales: ["en"],
84	  });
85	  const discounts: { coupon: string }[] = [];
86	  for (const c of p.coupons) discounts.push({ coupon: await couponId(stripe, c) });
87	  const subscription = await stripe.subscriptions.create({
88	    customer: customer.id,
89	    items: p.items.map((item, i) => ({ price: prices[i] ?? "", quantity: item.quantity })),
90	    billing_mode: { type: p.billing_mode },
91	    ...(discounts.length > 0 ? { discounts } : {}),
92	  });
93	  const target = subscription.items.data.find((i) => i.price.id === prices[p.change.item]);
94	  if (!target) throw new Error("subscription created without the changed item");
95	  const discount = p.change.discount ? await couponId(stripe, p.change.discount) : null;
96	
97	  let preview: Json;
98	  try {
99	    preview = toJson(
100	      await stripe.invoices.createPreview({
101	        subscription: subscription.id,
102	        subscription_details: {
103	          items: [
104	            {
105	              id: target.id,
106	              ...(newPrice !== null ? { price: newPrice } : {}),
107	              ...(p.change.quantity !== null ? { quantity: p.change.quantity } : {}),
108	            },
109	          ],
110	          proration_date: p.start + p.change.offset,
111	          ...(p.change.proration_behavior !== null
112	            ? { proration_behavior: p.change.proration_behavior }
113	            : {}),
114	        },
115	        ...(discount !== null ? { discounts: [{ coupon: discount }] } : {}),
116	      }),
117	    );
118	  } catch (e) {
119	    preview = errorJson(e);
120	  }
121	  const first =
122	    typeof subscription.latest_invoice === "string" ? subscription.latest_invoice : null;
123	  const invoice = first !== null ? await stripe.invoices.retrieve(first) : null;
124	  return {
125	    preview,
126	    first_invoice: invoice
127	      ? {
128	          subtotal: invoice.subtotal,
129	          total: invoice.total,
130	          amount_due: invoice.amount_due,
131	          status: invoice.status,
132	        }
133	      : null,
134	  };
135	}
