1	/**
2	 * State-graph exploration of the Customer Portal: walkthroughs only check the paths someone
3	 * thought of, so this probe clicks every visible, enabled button and same-site link, breadth
4	 * first, up to a depth, and records the graph of screens it reaches. Each path is replayed in a
5	 * fresh billing world, since a click can change the account. The graph is canonical (states
6	 * numbered in discovery order, actions in page order), so the same code on the clone must
7	 * reach the same screens through the same clicks.
8	 */
9	import type { Browser, Page } from "playwright";
10	import type Stripe from "stripe";
11	import { z } from "zod";
12	import type { Json } from "../../harness/src/json.ts";
13	import { launch, normalise, openPage, settle, setupWorld, World } from "./ui.ts";
14	
15	export const ExploreInput = World.extend({
16	  kind: z.literal("explore"),
17	  depth: z.number().int().min(1).max(4),
18	  max_states: z.number().int().min(1).max(40),
19	});
20	export type ExploreInput = z.infer<typeof ExploreInput>;
21	
22	interface Action {
23	  role: "button" | "link";
24	  name: string;
25	  nth: number;
26	}
27	
28	const label = (a: Action): string => `${a.role} "${a.name}"${a.nth > 0 ? ` #${a.nth}` : ""}`;
29	
30	// Waits until the accessibility tree has not changed for a second: screens animate in, and
31	// buttons show a transient label ("Canceling…") while their request runs.
32	async function stableScreen(page: Page): Promise<string[]> {
33	  await settle(page);
34	  let last = "";
35	  let same = 0;
36	  for (let i = 0; i < 40 && same < 2; i += 1) {
37	    await page.waitForTimeout(500);
38	    const now = await page.locator("body").ariaSnapshot();
39	    same = now === last ? same + 1 : 0;
40	    last = now;
41	  }
42	  return normalise(last);
43	}
44	
45	async function actions(page: Page): Promise<Action[]> {
46	  const origin = new URL(page.url()).origin;
47	  const out: Action[] = [];
48	  const seen = new Map<string, number>();
49	  for (const role of ["link", "button"] as const) {
50	    for (const el of await page.getByRole(role).all()) {
51	      const aria = await el.ariaSnapshot().catch(() => "");
52	      const name = /^- \w+ "((?:[^"\\]|\\.)*)"/.exec(aria)?.[1];
53	      if (name === undefined) continue;
54	      const key = `${role}\u0000${name}`;
55	      const nth = seen.get(key) ?? 0;
56	      seen.set(key, nth + 1);
57	      if (!(await el.isVisible()) || !(await el.isEnabled())) continue;
58	      const href = await el.getAttribute("href");
59	      if (href !== null && !href.startsWith("#") && new URL(href, page.url()).origin !== origin)
60	        continue;
61	      out.push({ role, name: name.replace(/\\(.)/g, "$1"), nth });
62	    }
63	  }
64	  return out;
65	}
66	
67	async function replay(
68	  browser: Browser,
69	  stripe: Stripe,
70	  world: World,
71	  path: Action[],
72	): Promise<{ screen: string[]; next: Action[] }> {
73	  const portal = await setupWorld(stripe, world);
74	  const page = await openPage(browser);
75	  try {
76	    await page.goto(portal.url);
77	    await page.getByRole("link").first().waitFor({ timeout: 20000 });
78	    for (const a of path) {
79	      await page.getByRole(a.role, { name: a.name, exact: true }).nth(a.nth).click();
80	      await stableScreen(page);
81	    }
82	    return { screen: await stableScreen(page), next: await actions(page) };
83	  } finally {
84	    await page.context().close();
85	  }
86	}
87	
88	export async function runExplore(
89	  stripe: Stripe,
90	  input: ExploreInput,
91	): Promise<Record<string, Json>> {
92	  const browser = await launch();
93	  const states = new Map<string, number>();
94	  const screens: string[][] = [];
95	  const edges: { from: number; action: string; to: number }[] = [];
96	  const queue: { path: Action[]; from: number | null }[] = [{ path: [], from: null }];
97	  let truncated = false;
98	  try {
99	    for (let node = queue.shift(); node; node = queue.shift()) {
100	      const { screen, next } = await replay(browser, stripe, input, node.path);
101	      const sig = screen.join("\n");
102	      const known = states.get(sig);
103	      const id = known ?? screens.length;
104	      const last = node.path.at(-1);
105	      if (node.from !== null && last) edges.push({ from: node.from, action: label(last), to: id });
106	      if (known !== undefined) continue;
107	      if (screens.length >= input.max_states) {
108	        truncated = true;
109	        break;
110	      }
111	      states.set(sig, id);
112	      screens.push(screen);
113	      if (node.path.length >= input.depth) continue;
114	      for (const a of next) queue.push({ path: [...node.path, a], from: id });
115	    }
116	  } finally {
117	    await browser.close();
118	  }
119	  return { graph: { states: screens, edges, truncated } };
120	}
