1	/**
2	 * The billing engine: discount allocation, proration arithmetic, and the plan of a subscription
3	 * change (which lines it bills, now or at the next renewal). Pure functions over the state; the
4	 * API layer turns their output into Stripe objects.
5	 */
6	import {
7	  get,
8	  type Billed,
9	  type Coupon,
10	  type DiscountAmount,
11	  type Line,
12	  type State,
13	  type SubItem,
14	  type Subscription,
15	} from "./state.ts";
16	import { addIntervals, money, periodAt, shortDate, type Interval } from "./time.ts";
17	
18	// ---------------------------------------------------------------- rounding
19	
20	// round(num / den) half away from zero, on exact integers (den > 0).
21	export function roundRatio(num: number, den: number): number {
22	  const sign = num < 0 ? -1 : 1;
23	  const a = Math.abs(num);
24	  return sign * Math.floor((2 * a + den) / (2 * den));
25	}
26	
27	// Percent with up to four decimals, as an exact integer fraction of 1 000 000.
28	const PPM = 1_000_000;
29	const ppm = (percent: number): number => Math.round(percent * 10_000);
30	
31	// ---------------------------------------------------------------- discounts
32	
33	export interface DiscSpec {
34	  id: string;
35	  percent_off: number | null;
36	  amount_off: number | null;
37	  once: boolean;
38	}
39	
40	export function specOf(state: State, discountId: string): DiscSpec | undefined {
41	  const d = get(state.discounts, discountId);
42	  const c = d ? get(state.coupons, d.coupon) : undefined;
43	  if (!d || !c) return undefined;
44	  return {
45	    id: d.id,
46	    percent_off: c.percent_off,
47	    amount_off: c.amount_off,
48	    once: c.duration === "once",
49	  };
50	}
51	
52	export function specsOf(state: State, ids: string[]): DiscSpec[] {
53	  return ids.map((id) => specOf(state, id)).filter((s): s is DiscSpec => s !== undefined);
54	}
55	
56	// Discounts apply one after another; each is spread over the discountable lines in proportion to
57	// what is left of them, with the rounding remainder on the last line. Result: [discount][line].
58	export function allocate(bases: number[], discounts: DiscSpec[]): number[][] {
59	  const left = bases.map((b) => Math.max(0, b));
60	  return discounts.map((d) => {
61	    const sum = left.reduce((a, b) => a + b, 0);
62	    const out = left.map(() => 0);
63	    if (sum <= 0) return out;
64	    let total: number;
65	    if (d.percent_off !== null) {
66	      const p = ppm(d.percent_off);
67	      total = roundRatio(sum * p, PPM);
68	      left.forEach((b, i) => {
69	        out[i] = Math.floor((b * p) / PPM);
70	      });
71	    } else {
72	      total = Math.min(d.amount_off ?? 0, sum);
73	      left.forEach((b, i) => {
74	        out[i] = Math.floor((total * b) / sum);
75	      });
76	    }
77	    // The rounding remainder goes one cent per line, from the last line backwards.
78	    let rest = total - out.reduce((a, b) => a + b, 0);
79	    const open = left.map((b, i) => (b > 0 ? i : -1)).filter((i) => i >= 0);
80	    for (
81	      let k = open.length - 1;
82	      rest > 0 && open.length > 0;
83	      k = k === 0 ? open.length - 1 : k - 1
84	    ) {
85	      const i = open[k] ?? 0;
86	      out[i] = (out[i] ?? 0) + 1;
87	      rest -= 1;
88	    }
89	    left.forEach((b, i) => {
90	      left[i] = b - (out[i] ?? 0);
91	    });
92	    return out;
93	  });
94	}
95	
96	export function couponLabel(c: Pick<Coupon, "percent_off" | "amount_off">): string {
97	  if (c.percent_off !== null) {
98	    const p = c.percent_off;
99	    return `${Number.isInteger(p * 10) ? p.toFixed(1) : String(p)}% off`;
100	  }
101	  return `${money(c.amount_off ?? 0)} off`;
102	}
103	
104	function withDiscounts(specs: DiscSpec[]): string {
105	  if (specs.length === 0) return "";
106	  if (specs.length > 1) return " (with discounts)";
107	  const [s] = specs;
108	  return s ? ` (with ${couponLabel(s)})` : "";
109	}
110	
111	// ---------------------------------------------------------------- lines
112	
113	export function priceOf(state: State, id: string) {
114	  const p = get(state.prices, id);
115	  if (!p) throw new Error(`unknown price ${id}`);
116	  return p;
117	}
118	
119	export function productName(state: State, priceId: string): string {
120	  const p = priceOf(state, priceId);
121	  return get(state.products, p.product)?.name ?? "";
122	}
123	
124	export function recurringDescription(state: State, priceId: string, quantity: number): string {
125	  const p = priceOf(state, priceId);
126	  return `${quantity} × ${productName(state, priceId)} (at ${money(p.unit_amount)} / ${p.interval})`;
127	}
128	
129	const qtyPrefix = (q: number): string => (q > 1 ? `${q} × ` : "");
130	
131	export function intervalOf(state: State, sub: Subscription): Interval {
132	  const first = sub.items[0];
133	  return first ? priceOf(state, first.price).interval : "month";
134	}
135	
136	// ---------------------------------------------------------------- change plan
137	
138	export interface ItemChange {
139	  id: string;
140	  price: string | null;
141	  quantity: number | null;
142	}
143	
144	export type Behavior = "create_prorations" | "none" | "always_invoice";
145	
146	export interface PlannedItem {
147	  id: string;
148	  price: string;
149	  quantity: number;
150	}
151	
152	export interface Plan {
153	  // Proration lines, without IDs.
154	  prorations: Omit<Line, "id" | "invoice_item">[];
155	  // The discounts each proration line actually carries (for its discount list).
156	  own: DiscSpec[][];
157	  items: PlannedItem[];
158	  // Discounts of the new state (a once coupon passed to the preview included).
159	  discounts: string[];
160	  immediate: boolean;
161	  // A classic interval change restarts the cycle at the clock time.
162	  reset: boolean;
163	  period_start: number;
164	  period_end: number;
165	  anchor: number;
166	  interval: Interval;
167	  proration_date: number;
168	  now: number;
169	}
170	
171	export interface PlanError {
172	  message: string;
173	  param: string | null;
174	}
175	
176	export interface PlanInput {
177	  changes: ItemChange[];
178	  proration_date: number | null;
179	  behavior: Behavior | null;
180	  // Discount IDs replacing the subscription's, or null to keep them.
181	  discounts: string[] | null;
182	  now: number;
183	}
184	
185	function creditDiscounts(
186	  state: State,
187	  billed: Billed | null,
188	): { spec: DiscSpec; amount: number }[] {
189	  if (!billed) return [];
190	  return billed.discounts
191	    .filter((d) => d.amount !== 0)
192	    .map((d) => ({ spec: specOf(state, d.discount), amount: d.amount }))
193	    .filter((x): x is { spec: DiscSpec; amount: number } => x.spec !== undefined);
194	}
195	
196	// Credit for the unused time of an item, from `prd` to the period end, carrying the discounts the
197	// item got on the invoice that billed the period (PRO-01, DSC-04).
198	export function creditLine(
199	  state: State,
200	  sub: Subscription,
201	  it: SubItem,
202	  prd: number,
203	): { line: Omit<Line, "id" | "invoice_item">; own: DiscSpec[] } {
204	  const oldPrice = priceOf(state, it.price);
205	  const P = sub.period_end - sub.period_start;
206	  const r = sub.period_end - prd;
207	  const b = oldPrice.unit_amount * it.quantity;
208	  const carried = creditDiscounts(state, it.billed);
209	  let credit: number;
210	  if (sub.billing_mode === "classic") {
211	    // Classic: the coupons apply to the credited item on its own (an amount-off coupon in full,
212	    // not its share of a multi-item invoice), then the net amount is prorated.
213	    const D = allocate(
214	      [b],
215	      carried.map((c) => c.spec),
216	    ).reduce((a, x) => a + (x[0] ?? 0), 0);
217	    credit = -roundRatio((b - D) * r, P);
218	  } else {
219	    credit = -(roundRatio(b * r, P) - carried.reduce((a, c) => a + roundRatio(c.amount * r, P), 0));
220	  }
221	  return {
222	    line: {
223	      amount: credit,
224	      description: `Unused time on ${qtyPrefix(it.quantity)}${productName(state, it.price)}${withDiscounts(carried.map((c) => c.spec))} after ${shortDate(prd)}`,
225	      period: { start: prd, end: sub.period_end },
226	      price: it.price,
227	      quantity: it.quantity,
228	      proration: true,
229	      discountable: false,
230	      discount_amounts: [],
231	      subscription_item: it.id,
232	      credited: it.billed ? { invoice: it.billed.invoice, line: it.billed.line } : null,
233	      unit_amount_decimal: null,
234	    },
235	    own: carried.map((c) => c.spec),
236	  };
237	}
238	
239	export function planChange(state: State, sub: Subscription, input: PlanInput): Plan | PlanError {
240	  const behavior = input.behavior ?? "create_prorations";
241	  if (behavior === "none" && input.proration_date !== null) {
242	    return {
243	      message: "Cannot specify proration date if no proration is being done",
244	      param: "proration_date",
245	    };
246	  }
247	  const prd = input.proration_date ?? input.now;
248	  if (prd < sub.period_start || prd > sub.period_end) {
249	    return {
250	      message: `Cannot specify proration date outside of current subscription period or current phase. The value should be between ${sub.period_start} and ${sub.period_end}.`,
251	      param: "proration_date",
252	    };
253	  }
254	  const oldInterval = intervalOf(state, sub);
255	  const items: PlannedItem[] = sub.items.map((it) => {
256	    const ch = input.changes.find((c) => c.id === it.id);
257	    if (!ch) return { id: it.id, price: it.price, quantity: it.quantity };
258	    const priceChanged = ch.price !== null && ch.price !== it.price;
259	    return {
260	      id: it.id,
261	      price: ch.price ?? it.price,
262	      quantity: ch.quantity ?? (priceChanged ? 1 : it.quantity),
263	    };
264	  });
265	  const firstPlanned = items[0];
266	  const newInterval = firstPlanned ? priceOf(state, firstPlanned.price).interval : oldInterval;
267	  const discounts =
268	    input.discounts ?? sub.discounts.filter((id) => get(state.discounts, id)?.used !== true);
269	  const chargeSpecs = specsOf(state, discounts);
270	
271	  let periodStart = sub.period_start;
272	  let periodEnd = sub.period_end;
273	  let anchor = sub.anchor;
274	  let reset = false;
275	  const intervalChange = newInterval !== oldInterval;
276	  if (intervalChange) {
277	    if (sub.billing_mode === "classic") {
278	      reset = true;
279	      periodStart = input.now;
280	      anchor = input.now;
281	      periodEnd = addIntervals(input.now, newInterval, 1);
282	    } else {
283	      periodEnd = addIntervals(sub.period_start, newInterval, 1);
284	      if (periodEnd < sub.period_end && prd >= periodEnd) {
285	        return {
286	          message: `You cannot specify \`proration_date\` past the updated subscription period end when using flexible billing mode. The value should be less than ${periodEnd}.`,
287	          param: null,
288	        };
289	      }
290	    }
291	  }
292	
293	  const prorations: Plan["prorations"] = [];
294	  const own: DiscSpec[][] = [];
295	  const prorates = behavior !== "none" && prd < sub.period_end;
296	  if (prorates) {
297	    sub.items.forEach((it: SubItem, i) => {
298	      const next = items[i];
299	      if (!next || (next.price === it.price && next.quantity === it.quantity)) return;
300	      const credit = creditLine(state, sub, it, prd);
301	      prorations.push(credit.line);
302	      own.push(credit.own);
303	      if (reset) return;
304	      // Charge for the remaining time on the new item, over the new period.
305	      const newPrice = priceOf(state, next.price);
306	      const n = newPrice.unit_amount * next.quantity;
307	      const P2 = periodEnd - periodStart;
308	      const r2 = periodEnd - prd;
309	      const e2 = prd - periodStart;
310	      const D2 = allocate([n], chargeSpecs).map((x) => x[0] ?? 0);
311	      const base =
312	        sub.billing_mode === "classic" ? roundRatio(n * r2, P2) : Math.round(n * (1 - e2 / P2));
313	      // Flexible discounts the full-period amount, then prorates the discount (DSC-02); classic
314	      // prorates first and takes a percent-off on the prorated amount (DSC-04).
315	      let left = base;
316	      const prorated = chargeSpecs.map((s, k) => {
317	        const d =
318	          sub.billing_mode === "classic" && s.percent_off !== null
319	            ? roundRatio(Math.max(0, left) * ppm(s.percent_off), PPM)
320	            : roundRatio((D2[k] ?? 0) * r2, P2);
321	        left -= d;
322	        return d;
323	      });
324	      const applied = chargeSpecs.filter((_, k) => (prorated[k] ?? 0) !== 0);
325	      const charge = left;
326	      prorations.push({
327	        amount: charge,
328	        description: `Remaining time on ${qtyPrefix(next.quantity)}${productName(state, next.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
329	        period: { start: prd, end: periodEnd },
330	        price: next.price,
331	        quantity: next.quantity,
332	        proration: true,
333	        discountable: false,
334	        discount_amounts: [],
335	        subscription_item: it.id,
336	        credited: null,
337	        unit_amount_decimal: null,
338	      });
339	      own.push(applied);
340	    });
341	  }
342	  const immediate = reset || (behavior === "always_invoice" && prorations.length > 0);
343	  return {
344	    prorations,
345	    own,
346	    items,
347	    discounts,
348	    immediate,
349	    reset,
350	    period_start: periodStart,
351	    period_end: periodEnd,
352	    anchor,
353	    interval: newInterval,
354	    proration_date: prd,
355	    now: input.now,
356	  };
357	}
