363	// ---------------------------------------------------------------- invoice assembly
364	
365	export interface Draft {
366	  lines: Line[];
367	  discounts: string[];
368	  total_discount_amounts: DiscountAmount[];
369	  created: number;
370	  period_start: number;
371	  period_end: number;
372	  immediate: boolean;
373	}
374	
375	// The invoice a plan produces: now (immediate) or at the next renewal (prorations plus the next
376	// full period of every item).
377	export function draftFromPlan(
378	  state: State,
379	  sub: Subscription,
380	  plan: Plan,
381	  ids: { line: () => string; item: () => string },
382	  mode: Subscription["billing_mode"],
383	): Draft {
384	  // once coupons never discount the renewal (DSC-05) nor show on the invoice.
385	  const top = plan.discounts.filter((id) => specOf(state, id)?.once === false);
386	  const topSpecs = specsOf(state, top);
387	  const lines: Line[] = plan.prorations.map((p) => ({
388	    ...p,
389	    id: ids.line(),
390	    invoice_item: ids.item(),
391	  }));
392	  const recurring: Line[] = [];
393	  if (plan.reset) {
394	    for (const it of plan.items) {
395	      const changed = plan.prorations.some((p) => p.subscription_item === it.id);
396	      if (!changed) continue;
397	      recurring.push(recurringLine(state, it, plan.period_start, plan.period_end, ids.line()));
398	    }
399	  } else if (!plan.immediate) {
400	    const next = periodAt(plan.anchor, plan.interval, plan.period_end)[1];
401	    for (const it of plan.items) {
402	      recurring.push(recurringLine(state, it, plan.period_end, next, ids.line()));
403	    }
404	  }
405	  const alloc = allocate(
406	    recurring.map((l) => l.amount),
407	    topSpecs,
408	  );
409	  recurring.forEach((l, i) => {
410	    l.discount_amounts = topSpecs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
411	  });
412	  lines.forEach((l, i) => {
413	    const mine = plan.own[i] ?? [];
414	    // Observed only (no documented rule): which discounts a proration line lists, at 0.
415	    const isCredit = l.amount < 0 || l.description.startsWith("Unused");
416	    let list: string[];
417	    if (mode === "classic") list = top;
418	    else if (plan.immediate && !isCredit) list = mine.map((s) => s.id);
419	    else if (top.length > 0) list = plan.immediate ? top : top.slice(0, 1);
420	    else list = mine.map((s) => s.id);
421	    l.discount_amounts = list.map((discount) => ({ discount, amount: 0 }));
422	  });
423	  const all = [...lines, ...recurring];
424	  const tda = top.map((discount) => ({
425	    discount,
426	    amount: all.reduce(
427	      (a, l) =>
428	        a +
429	        l.discount_amounts.filter((d) => d.discount === discount).reduce((x, d) => x + d.amount, 0),
430	      0,
431	    ),
432	  }));
433	  const immediate = plan.immediate;
434	  return {
435	    lines: all,
436	    discounts: top,
437	    total_discount_amounts: tda,
438	    created: immediate ? plan.now : plan.period_end,
439	    period_start: immediate ? plan.now : sub.period_start,
440	    period_end: immediate ? plan.now : plan.period_end,
441	    immediate,
442	  };
443	}
444	
445	export function recurringLine(
446	  state: State,
447	  it: PlannedItem,
448	  start: number,
449	  end: number,
450	  id: string,
451	): Line {
452	  const p = priceOf(state, it.price);
453	  return {
454	    id,
455	    amount: p.unit_amount * it.quantity,
456	    description: recurringDescription(state, it.price, it.quantity),
457	    period: { start, end },
458	    price: it.price,
459	    quantity: it.quantity,
460	    proration: false,
461	    discountable: true,
462	    discount_amounts: [],
463	    subscription_item: it.id,
464	    invoice_item: null,
465	    credited: null,
466	    unit_amount_decimal: String(p.unit_amount),
467	  };
468	}
469	
470	export function totals(lines: Line[], tda: DiscountAmount[]) {
471	  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
472	  const discount = tda.reduce((a, d) => a + d.amount, 0);
473	  return { subtotal, total: subtotal - discount };
474	}
