32	export const ok = (body: Json): CloneResponse => ({ status: 200, body });
33	export const fail = (
34	  status: number,
35	  message: string,
36	  param: string | null = null,
37	): CloneResponse => ({
38	  status,
39	  body: { error: { type: "invalid_request_error", message, param } },
40	});
41	const missing = (what: string, id: string): CloneResponse =>
42	  fail(404, `No such ${what}: '${id}'`, "id");
