44	export function str(v: Json | undefined): string | null {
45	  return typeof v === "string" ? v : typeof v === "number" ? String(v) : null;
46	}
47	export function num(v: Json | undefined): number | null {
48	  const s = str(v);
49	  if (s === null || s === "") return null;
50	  const n = Number(s);
51	  return Number.isFinite(n) ? n : null;
52	}
53	export function obj(v: Json | undefined): Params {
54	  return v !== null && typeof v === "object" && !Array.isArray(v) ? v : {};
55	}
56	export function arr(v: Json | undefined): Json[] {
57	  if (Array.isArray(v)) return v;
58	  if (v !== null && typeof v === "object") return Object.values(v);
59	  return [];
60	}
61	const bool = (v: Json | undefined): boolean => v === true || v === "true";
