63	function newDiscount(
64	  state: State,
65	  coupon: string,
66	  customer: string,
67	  sub: string | null,
68	  now: number,
69	): Discount {
70	  const d: Discount = {
71	    id: mint(state, "di"),
72	    coupon,
73	    customer,
74	    subscription: sub,
75	    start: now,
76	    used: false,
77	  };
78	  state.discounts[d.id] = d;
79	  return d;
