82	// pm_card_* tokens resolve to a new payment method each time.
83	function paymentMethodFrom(state: State, token: string, customer: string | null): string {
84	  if (get(state.payment_methods, token)) return token;
85	  const id = mint(state, "pm");
86	  state.payment_methods[id] = { id, customer, fails: token.includes("Fail") };
87	  return id;
