90	// ------------------------------------------------------------------ first invoice
91	
92	export function billFirstInvoice(state: State, sub: Subscription, now: number): Invoice {
93	  const id = mint(state, "in");
94	  const trial = sub.status === "trialing";
95	  const specs = trial ? [] : specsOf(state, sub.discounts);
96	  const lines: Line[] = sub.items.map((it) => {
97	    const p = priceOf(state, it.price);
98	    return {
99	      id: mint(state, "il"),
100	      amount: trial ? 0 : p.unit_amount * it.quantity,
101	      description: trial
102	        ? `Free trial for ${it.quantity} × ${productName(state, it.price)}`
103	        : recurringDescription(state, it.price, it.quantity),
104	      period: { start: sub.period_start, end: sub.period_end },
105	      price: it.price,
106	      quantity: it.quantity,
107	      proration: false,
108	      discountable: true,
109	      discount_amounts: [],
110	      subscription_item: it.id,
111	      invoice_item: null,
112	      credited: null,
113	      unit_amount_decimal: String(p.unit_amount),
114	    };
115	  });
116	  const alloc = allocate(
117	    lines.map((l) => l.amount),
118	    specs,
119	  );
120	  lines.forEach((l, i) => {
121	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
122	  });
123	  sub.items.forEach((it, i) => {
124	    const l = lines[i];
125	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
126	  });
127	  for (const s of specs) {
128	    const d = get(state.discounts, s.id);
129	    if (d && s.once) d.used = true;
130	  }
131	  const tda = specs.map((s, k) => ({
132	    discount: s.id,
133	    amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
134	  }));
135	  const inv: Invoice = {
136	    id,
137	    customer: sub.customer,
138	    subscription: sub.id,
139	    lines,
140	    discounts: specs.map((s) => s.id),
141	    total_discount_amounts: tda,
142	    billing_reason: "subscription_create",
143	    status: "paid",
144	    created: now,
145	    period_start: now,
146	    period_end: now,
147	    attempt_count: 0,
148	    amount_paid: 0,
149	    auto_advance: false,
150	    next_payment_attempt: null,
151	    proration_date: null,
152	    retries: [],
153	  };
154	  const due = Math.max(
155	    0,
156	    lines.reduce((a, l) => a + l.amount, 0) - tda.reduce((a, d) => a + d.amount, 0),
157	  );
158	  inv.amount_paid = due;
159	  inv.attempt_count = due > 0 ? 1 : 0;
160	  state.invoices[id] = inv;
161	  sub.latest_invoice = id;
162	  return inv;
163	}
