167	function createSubscription(state: State, p: Params): CloneResponse {
168	  const customerId = str(p.customer) ?? "";
169	  const customer = get(state.customers, customerId);
170	  if (!customer) return missing("customer", customerId);
171	  const now = nowFor(state, customerId);
172	  const id = mint(state, "sub");
173	  const items = arr(p.items).map((raw) => {
174	    const it = obj(raw);
175	    return {
176	      id: mint(state, "si"),
177	      price: str(it.price) ?? "",
178	      quantity: num(it.quantity) ?? 1,
179	      created: now,
180	      billed: null,
181	    };
182	  });
183	  for (const it of items) if (!get(state.prices, it.price)) return missing("price", it.price);
184	  const first = items[0];
185	  const interval: Interval = first ? priceOf(state, first.price).interval : "month";
186	  const trialDays = num(p.trial_period_days);
187	  const trialEnd = trialDays !== null ? now + trialDays * 86400 : null;
188	  const mode = str(obj(p.billing_mode).type) === "classic" ? "classic" : "flexible";
189	  const sub: Subscription = {
190	    id,
191	    customer: customerId,
192	    items,
193	    billing_mode: mode,
194	    discounts: [],
195	    anchor: trialEnd ?? now,
196	    period_start: now,
197	    period_end: trialEnd ?? addIntervals(now, interval, 1),
198	    status: trialEnd !== null ? "trialing" : "active",
199	    created: now,
200	    latest_invoice: null,
201	    cancel_at_period_end: false,
202	    cancel_at: null,
203	    canceled_at: null,
204	    ended_at: null,
205	    trial_start: trialEnd !== null ? now : null,
206	    trial_end: trialEnd,
207	  };
208	  for (const raw of arr(p.discounts)) {
209	    const coupon = str(obj(raw).coupon) ?? "";
210	    if (!get(state.coupons, coupon)) return missing("coupon", coupon);
211	    sub.discounts.push(newDiscount(state, coupon, customerId, id, now).id);
212	  }
213	  state.subscriptions[id] = sub;
214	  billFirstInvoice(state, sub, now);
215	  return ok(subscriptionJson(state, sub, false));
216	}
