218	function previewInvoice(state: State, p: Params): CloneResponse {
219	  const subId = str(p.subscription) ?? "";
220	  const sub = get(state.subscriptions, subId);
221	  if (!sub) return missing("subscription", subId);
222	  const details = obj(p.subscription_details);
223	  const changes: ItemChange[] = arr(details.items).map((raw) => {
224	    const it = obj(raw);
225	    return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
226	  });
227	  const now = nowFor(state, sub.customer);
228	  const discounts =
229	    p.discounts !== undefined
230	      ? arr(p.discounts).map(
231	          (raw) => newDiscount(state, str(obj(raw).coupon) ?? "", sub.customer, null, now).id,
232	        )
233	      : null;
234	  const behavior = str(details.proration_behavior) as Behavior | null;
235	  const plan = planChange(state, sub, {
236	    changes,
237	    proration_date: num(details.proration_date),
238	    behavior,
239	    discounts,
240	    now,
241	  });
242	  if (isPlanError(plan)) return fail(400, plan.message, plan.param);
243	  const draft = draftFromPlan(
244	    state,
245	    sub,
246	    plan,
247	    { line: () => mint(state, "il_tmp"), item: () => mint(state, "ii") },
248	    sub.billing_mode,
249	  );
250	  const inv: Invoice = {
251	    id: mint(state, "upcoming_in"),
252	    customer: sub.customer,
253	    subscription: sub.id,
254	    lines: draft.lines,
255	    discounts: draft.discounts,
256	    total_discount_amounts: draft.total_discount_amounts,
257	    billing_reason: "upcoming",
258	    status: "draft",
259	    created: draft.created,
260	    period_start: draft.period_start,
261	    period_end: draft.period_end,
262	    attempt_count: 0,
263	    amount_paid: 0,
264	    auto_advance: !draft.immediate,
265	    next_payment_attempt: draft.immediate ? null : draft.created + 3600,
266	    proration_date: plan.proration_date,
267	    retries: [],
268	  };
269	  return ok(invoiceJson(state, inv, true));
270	}
