323	export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
324	  const parts = req.path.split("/").filter((s) => s !== "");
325	  if (parts[0] !== "v1") return null;
326	  const [, a, b, c, d] = parts;
327	  const m = req.method;
328	
329	  if (a === "test_helpers" && b === "test_clocks") {
330	    if (m === "POST" && c === undefined) {
331	      const id = mint(state, "clock");
332	      const t = num(p.frozen_time) ?? 0;
333	      state.clocks[id] = { id, frozen_time: t, created: t };
334	      return ok(clockJson(state, id));
335	    }
336	    const clock = c !== undefined ? get(state.clocks, c) : undefined;
337	    if (!clock || c === undefined) return missing("test_clock", c ?? "");
338	    if (m === "GET") return ok(clockJson(state, c));
339	    if (m === "POST" && d === "advance") {
340	      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
341	      return ok(clockJson(state, c));
342	    }
343	  }
344	  if (a === "products" && m === "POST" && b === undefined) {
345	    const id = mint(state, "prod");
346	    state.products[id] = { id, name: str(p.name) ?? "" };
347	    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
348	  }
349	  if (a === "prices" && m === "POST" && b === undefined) {
350	    const id = mint(state, "price");
351	    const interval = str(obj(p.recurring).interval) === "year" ? "year" : "month";
352	    state.prices[id] = {
353	      id,
354	      product: str(p.product) ?? "",
355	      unit_amount: num(p.unit_amount) ?? 0,
356	      currency: str(p.currency) ?? "usd",
357	      interval,
358	    };
359	    return ok(priceJson(state, id));
360	  }
361	  if (a === "coupons" && m === "POST" && b === undefined) {
362	    const id = mint(state, "coupon");
363	    const coupon = {
364	      id,
365	      percent_off: num(p.percent_off),
366	      amount_off: num(p.amount_off),
367	      duration: str(p.duration) === "once" ? ("once" as const) : ("forever" as const),
368	    };
369	    state.coupons[id] = coupon;
370	    return ok(couponJson(coupon));
371	  }
372	  if (a === "customers") {
373	    if (m === "POST" && b === undefined) {
374	      const id = mint(state, "cus");
375	      const clock = str(p.test_clock);
376	      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
377	      const pmToken = str(p.payment_method);
378	      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
379	      state.customers[id] = { id, clock, default_payment_method: pm, created: now };
380	      return ok({
381	        id,
382	        object: "customer",
383	        test_clock: clock,
384	        invoice_settings: { default_payment_method: pm },
385	      });
386	    }
387	    const cus = b !== undefined ? get(state.customers, b) : undefined;
388	    if (!cus || b === undefined) return missing("customer", b ?? "");
389	    if (m === "POST" && c === undefined) {
390	      const dpm = str(obj(p.invoice_settings).default_payment_method);
391	      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
392	    }
393	    return ok({
394	      id: cus.id,
395	      object: "customer",
396	      test_clock: cus.clock,
397	      invoice_settings: { default_payment_method: cus.default_payment_method },
398	    });
399	  }
400	  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
401	    const id = paymentMethodFrom(state, b, str(p.customer));
402	    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
403	  }
404	  if (a === "subscriptions") {
405	    if (m === "POST" && b === undefined) return createSubscription(state, p);
406	    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
407	    if (!sub || b === undefined) return missing("subscription", b ?? "");
408	    if (m === "GET") {
409	      const expand = arr(p.expand).map(str);
410	      return ok(subscriptionJson(state, sub, expand.includes("latest_invoice")));
411	    }
412	    if (m === "DELETE") {
413	      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
414	      return ok(subscriptionJson(state, sub, false));
415	    }
416	    if (m === "POST") return updateSubscription(state, sub, p);
417	  }
418	  if (a === "invoices") {
419	    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
420	    if (m === "GET" && b === undefined) return listInvoices(state, p);
421	    if (m === "GET" && b !== undefined) {
422	      const inv = get(state.invoices, b);
423	      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
424	    }
425	  }
426	  if (a === "invoiceitems" && m === "GET" && b === undefined) return listInvoiceItems(state, p);
427	  return null;
428	}
429	
430	function clockJson(state: State, id: string): Json {
431	  const c = get(state.clocks, id);
432	  return {
433	    id,
434	    object: "test_helpers.test_clock",
435	    created: c?.created ?? 0,
436	    frozen_time: c?.frozen_time ?? 0,
437	    livemode: false,
438	    status: "ready",
439	  };
440	}
