171	export function seed(): State {
172	  return {
173	    n: 0,
174	    clocks: {},
175	    products: {},
176	    prices: {},
177	    coupons: {},
178	    customers: {},
179	    payment_methods: {},
180	    discounts: {},
181	    subscriptions: {},
182	    invoices: {},
183	    invoice_items: {},
184	    configs: {},
185	    sessions: {},
186	  };
187	}
188	
189	const ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
190	
191	// Deterministic IDs: the same calls after a reset mint the same IDs.
192	export function mint(state: State, prefix: string): string {
193	  state.n += 1;
194	  const n = state.n;
195	  let x = n * 7919 + 104729;
196	  let s = "";
197	  while (s.length < 14) {
198	    s = (ALPHABET[x % 62] ?? "0") + s;
199	    x = Math.floor(x / 62) + n * 31;
200	  }
201	  // Stripe IDs start with an upper-case letter or digit after the prefix; keep one fixed shape.
202	  return `${prefix}_1${s}`;
203	}
204	
205	export function get<T>(table: Record<string, T>, id: string): T | undefined {
206	  return Object.hasOwn(table, id) ? table[id] : undefined;
207	}
208	
209	// The clock time a customer lives on (its test clock), or the subscription's creation time.
210	export function nowFor(state: State, customer: string): number {
211	  const c = get(state.customers, customer);
212	  const clock = c?.clock ? get(state.clocks, c.clock) : undefined;
213	  return clock ? clock.frozen_time : Math.floor(Date.now() / 1000);
214	}
