1	/**
2	 * The Customer Portal: the configuration and session API, the portal page, and the JSON
3	 * endpoints the page calls under /v1/billing_portal/sessions/<bps>/... (UI-01..14).
4	 */
5	import type { CloneRequest, CloneResponse } from "../../../harness/src/clone-kit.ts";
6	import type { Json } from "../../../harness/src/json.ts";
7	import { arr, fail, num, obj, ok, str } from "./api.ts";
8	import {
9	  allocate,
10	  draftFromPlan,
11	  isPlanError,
12	  planChange,
13	  priceOf,
14	  productName,
15	  specsOf,
16	  type DiscSpec,
17	  type ItemChange,
18	} from "./billing.ts";
19	import { ACCOUNT_NAME, CARD } from "./objects.ts";
20	import { portalPage } from "./page.ts";
21	import {
22	  get,
23	  mint,
24	  nowFor,
25	  type Line,
26	  type PortalSession,
27	  type State,
28	  type Subscription,
29	} from "./state.ts";
30	
31	type Params = Record<string, Json>;
32	
33	// Discounts that will apply to the next renewal (forever coupons; a spent once coupon is gone).
34	function renewalSpecs(state: State, sub: Subscription): DiscSpec[] {
35	  return specsOf(state, sub.discounts).filter((s) => !s.once);
36	}
37	
38	function couponText(s: DiscSpec): string {
39	  if (s.percent_off !== null) return `${String(s.percent_off)}% off`;
40	  return `$${((s.amount_off ?? 0) / 100).toFixed(2)} off`;
41	}
42	
43	// The recurring amount of a set of items after the renewal discounts.
44	function recurringNet(
45	  state: State,
46	  sub: Subscription,
47	  items: { price: string; quantity: number }[],
48	): number {
49	  const bases = items.map((it) => priceOf(state, it.price).unit_amount * it.quantity);
50	  const alloc = allocate(bases, renewalSpecs(state, sub));
51	  const off = alloc.reduce((a, row) => a + row.reduce((x, y) => x + y, 0), 0);
52	  return bases.reduce((a, b) => a + b, 0) - off;
53	}
54	
55	function pendingLines(state: State, sub: Subscription): Line[] {
56	  return Object.values(state.invoice_items)
57	    .filter((ii) => ii.subscription === sub.id && ii.invoice === null)
58	    .map((ii) => ii.line);
59	}
60	
61	// The next invoice of a subscription: pending prorations plus the renewal, discounted.
62	function upcoming(state: State, sub: Subscription): Json {
63	  const now = nowFor(state, sub.customer);
64	  const plan = planChange(state, sub, {
65	    changes: [],
66	    proration_date: null,
67	    behavior: "create_prorations",
68	    discounts: null,
69	    now,
70	  });
71	  if (isPlanError(plan)) return null;
72	  let n = 0;
73	  const draft = draftFromPlan(
74	    state,
75	    sub,
76	    plan,
77	    {
78	      line: () => `il_tmp_${String((n += 1))}`,
79	      item: () => `ii_tmp_${String((n += 1))}`,
80	    },
81	    sub.billing_mode,
82	  );
83	  const pending = pendingLines(state, sub);
84	  const lines = [...pending, ...draft.lines];
85	  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
86	  const discounts = draft.total_discount_amounts.map((d) => {
87	    const spec = specsOf(state, [d.discount])[0];
88	    return { label: spec ? couponText(spec) : "", amount: d.amount };
89	  });
90	  const total = subtotal - discounts.reduce((a, d) => a + d.amount, 0);
91	  const label = (l: Line): string => {
92	    const name = productName(state, l.price);
93	    if (!l.proration) return name;
94	    return l.amount < 0 || l.description.startsWith("Unused")
95	      ? `Prorated credit from ${name}`
96	      : `Prorated charge for ${name}`;
97	  };
98	  return {
99	    prorations: pending.map((l) => ({
100	      label: label(l),
101	      amount: l.amount,
102	      start: sub.period_start,
103	      end: sub.period_end,
104	    })),
105	    renewal: draft.lines.map((l) => ({
106	      label: label(l),
107	      amount: l.amount,
108	      quantity: l.quantity,
109	      start: l.period.start,
110	      end: l.period.end,
111	    })),
112	    subtotal,
113	    discounts,
114	    has_discount: discounts.some((d) => d.amount !== 0),
115	    total,
116	    amount_due: Math.max(0, total),
117	  };
118	}
119	
120	function subscriptionView(state: State, sub: Subscription): Json {
121	  return {
122	    id: sub.id,
123	    status: sub.status,
124	    period_start: sub.period_start,
125	    period_end: sub.period_end,
126	    cancel_at: sub.cancel_at,
127	    items: sub.items.map((it) => {
128	      const p = priceOf(state, it.price);
129	      return {
130	        id: it.id,
131	        price: it.price,
132	        product: p.product,
133	        name: productName(state, it.price),
134	        unit_amount: p.unit_amount,
135	        interval: p.interval,
136	        quantity: it.quantity,
137	      };
138	    }),
139	    net: recurringNet(state, sub, sub.items),
140	    pending: pendingLines(state, sub).length,
141	    upcoming: upcoming(state, sub),
142	  };
143	}
144	
145	function sessionOf(state: State, id: string): PortalSession | undefined {
146	  return get(state.sessions, id);
147	}
148	
149	function subsOf(state: State, customer: string): Subscription[] {
150	  return Object.values(state.subscriptions).filter(
151	    (s) => s.customer === customer && s.status !== "canceled",
152	  );
153	}
154	
155	function sessionApi(
156	  state: State,
157	  session: PortalSession,
158	  method: string,
159	  rest: string[],
160	  p: Params,
161	): CloneResponse {
162	  const config = get(state.configs, session.configuration);
163	  const [a, b, c] = rest;
164	  if (method === "GET" && a === undefined) {
165	    return ok({
166	      id: session.id,
167	      object: "billing_portal.session",
168	      customer: session.customer,
169	      account_name: ACCOUNT_NAME,
170	      configuration: {
171	        id: session.configuration,
172	        cancel_enabled: config?.cancel_enabled ?? false,
173	        allowed_updates: config?.allowed_updates ?? [],
174	      },
175	    });
176	  }
177	  if (method === "GET" && a === "customer") {
178	    return ok({ id: session.customer, object: "customer", balance: 0 });
179	  }
180	  if (method === "GET" && a === "payment_methods") {
181	    const cus = get(state.customers, session.customer);
182	    return ok({
183	      object: "list",
184	      data: cus?.default_payment_method
185	        ? [{ id: cus.default_payment_method, ...CARD, default: true }]
186	        : [],
187	    });
188	  }
189	  if (method === "GET" && a === "subscriptions" && b === undefined) {
190	    return ok({
191	      object: "list",
192	      data: subsOf(state, session.customer).map((s) => subscriptionView(state, s)),
193	    });
194	  }
195	  if (method === "GET" && a === "update_preview") {
196	    const sub = subsOf(state, session.customer)[0];
197	    if (!sub) return fail(404, "No subscription");
198	    const changes: ItemChange[] = arr(p.items).map((raw) => {
199	      const it = obj(raw);
200	      return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
201	    });
202	    const items = sub.items.map((it) => {
203	      const ch = changes.find((x) => x.id === it.id);
204	      return { price: ch?.price ?? it.price, quantity: ch?.quantity ?? it.quantity };
205	    });
206	    return ok({
207	      object: "billing_portal.update_preview",
208	      recurring_amount: recurringNet(state, sub, items),
209	      has_discount: renewalSpecs(state, sub).length > 0,
210	      generates_immediate_invoice: false,
211	      next_billing_date: sub.period_end,
212	    });
213	  }
214	  if (a !== "subscriptions" || b === undefined) return fail(404, "Not found");
215	  const sub = get(state.subscriptions, b);
216	  if (!sub || sub.customer !== session.customer) return fail(404, "No such subscription");
217	  if (method === "GET" && c === undefined) {
218	    const plans = (config?.products ?? []).flatMap((prod) =>
219	      prod.prices.map((priceId) => {
220	        const pr = priceOf(state, priceId);
221	        return {
222	          product: prod.product,
223	          price: priceId,
224	          name: productName(state, priceId),
225	          unit_amount: pr.unit_amount,
226	          interval: pr.interval,
227	        };
228	      }),
229	    );
230	    return ok({ ...obj(subscriptionView(state, sub)), plans });
231	  }
232	  if (method === "GET" && c === "retention_coupon") return ok({ coupon: null });
233	  const now = nowFor(state, sub.customer);
234	  if (method === "POST" && c === "cancel") {
235	    sub.cancel_at = sub.period_end;
236	    sub.canceled_at = now;
237	    return ok(subscriptionView(state, sub));
238	  }
239	  if (method === "POST" && c === "reactivate") {
240	    sub.cancel_at = null;
241	    sub.canceled_at = null;
242	    sub.cancel_at_period_end = false;
243	    return ok(subscriptionView(state, sub));
244	  }
245	  if (method === "POST" && c === undefined) {
246	    const changes: ItemChange[] = arr(p.recurring_items).map((raw) => {
247	      const it = obj(raw);
248	      return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
249	    });
250	    const plan = planChange(state, sub, {
251	      changes,
252	      proration_date: null,
253	      behavior: "create_prorations",
254	      discounts: null,
255	      now,
256	    });
257	    if (isPlanError(plan)) return fail(400, plan.message, plan.param);
258	    for (const l of plan.prorations) {
259	      const id = mint(state, "ii");
260	      state.invoice_items[id] = {
261	        id,
262	        customer: sub.customer,
263	        subscription: sub.id,
264	        line: { ...l, id: "", invoice_item: id },
265	        invoice: null,
266	      };
267	    }
268	    sub.items.forEach((it) => {
269	      const next = plan.items.find((x) => x.id === it.id);
270	      if (next) {
271	        it.price = next.price;
272	        it.quantity = next.quantity;
273	      }
274	    });
275	    return ok(subscriptionView(state, sub));
276	  }
277	  return fail(404, "Not found");
278	}
279	
280	export function handlePortal(state: State, req: CloneRequest, p: Params): CloneResponse | null {
281	  const parts = req.path.split("/").filter((s) => s !== "");
282	  if (
283	    parts[0] === "p" &&
284	    parts[1] === "session" &&
285	    parts[2] !== undefined &&
286	    req.method === "GET"
287	  ) {
288	    const id = parts[2].replace(/^test_/, "bps_");
289	    const session = sessionOf(state, id);
290	    if (!session) return { status: 404, body: "Not found", contentType: "text/plain" };
291	    return { status: 200, body: portalPage(session.id), contentType: "text/html; charset=utf-8" };
292	  }
293	  if (parts[0] !== "v1" || parts[1] !== "billing_portal") return null;
294	  const [, , kind, id, ...rest] = parts;
295	  if (kind === "configurations" && req.method === "POST" && id === undefined) {
296	    const features = obj(p.features);
297	    const cancel = obj(features.subscription_cancel);
298	    const update = obj(features.subscription_update);
299	    const cfgId = mint(state, "bpc");
300	    state.configs[cfgId] = {
301	      id: cfgId,
302	      cancel_enabled: cancel.enabled === "true",
303	      allowed_updates: arr(update.default_allowed_updates).map((x) => str(x) ?? ""),
304	      products: arr(update.products).map((raw) => {
305	        const pr = obj(raw);
306	        return { product: str(pr.product) ?? "", prices: arr(pr.prices).map((x) => str(x) ?? "") };
307	      }),
308	    };
309	    return ok({ id: cfgId, object: "billing_portal.configuration" });
310	  }
311	  if (kind === "sessions" && req.method === "POST" && id === undefined) {
312	    const customer = str(p.customer) ?? "";
313	    if (!get(state.customers, customer)) return fail(404, `No such customer: '${customer}'`);
314	    const sid = mint(state, "bps");
315	    state.sessions[sid] = {
316	      id: sid,
317	      customer,
318	      configuration: str(p.configuration) ?? "",
319	      created: nowFor(state, customer),
320	    };
321	    const host = typeof req.headers.host === "string" ? req.headers.host : "127.0.0.1";
322	    return ok({
323	      id: sid,
324	      object: "billing_portal.session",
325	      customer,
326	      url: `http://${host}/p/session/${sid.replace(/^bps_/, "test_")}`,
