225	// Ten dev fixtures spread over the sorted list, so that every kind of probe tends to be sampled.
226	function sample<T extends { id: string }>(xs: T[], n = 10): T[] {
227	  const sorted = [...xs].sort((a, b) => a.id.localeCompare(b.id));
228	  if (sorted.length <= n) return sorted;
