1	/**
2	 * Fixtures are the frozen evaluator: a probe's input and the target's recorded output. This
3	 * module owns their on-disk format, the dev/holdout split and the hash lock that `verify` checks
4	 * before every run.
5	 */
6	import { createHash } from "node:crypto";
7	import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
8	import { join } from "node:path";
9	import { z } from "zod";
10	import { JsonSchema } from "./json.ts";
11	
12	export const FixtureSchema = z.object({
13	  id: z.string(),
14	  rules: z.array(z.string()).min(1),
15	  input: JsonSchema,
16	  observed: z.record(z.string(), JsonSchema),
17	  noise: z.array(z.string()).describe("paths that differed between two recordings of this probe"),
18	  recorded_at: z.string(),
19	});
20	export type Fixture = z.infer<typeof FixtureSchema>;
21	export type Split = "dev" | "holdout";
22	
23	const LockSchema = z.object({
24	  policy: z.string(),
25	  fixtures: z.record(z.string(), z.string()),
26	  // Everything that shapes the score besides fixtures: the target's driver code and the harness.
27	  code: z.record(z.string(), z.string()).optional(),
28	});
29	
30	export const sha256 = (s: string): string => createHash("sha256").update(s).digest("hex");
31	
32	// A quarter of ordinary probes go to the holdout by hash of their ID. A probe whose ID starts with
33	// `hold-` belongs to a dedicated, pre-registered holdout batch and never goes to dev. One whose ID
34	// starts with `dev-` was designed after seeing failures, so it can train but never certify.
35	export function splitOf(id: string): Split {
36	  if (id.startsWith("hold-")) return "holdout";
37	  if (id.startsWith("dev-")) return "dev";
38	  return Number.parseInt(sha256(id).slice(0, 2), 16) % 4 === 0 ? "holdout" : "dev";
39	}
40	
41	export function targetDir(target: string): string {
42	  return join(import.meta.dirname, "..", "..", "targets", target);
43	}
44	
45	const fixturesDir = (target: string, split: Split): string =>
46	  join(targetDir(target), "fixtures", split);
47	
48	export function fixturePath(target: string, id: string): string {
49	  return join(fixturesDir(target, splitOf(id)), `${id}.json`);
50	}
51	
52	export function writeFixture(target: string, f: Fixture): void {
53	  mkdirSync(fixturesDir(target, splitOf(f.id)), { recursive: true });
54	  writeFileSync(fixturePath(target, f.id), `${JSON.stringify(f, null, 2)}\n`);
55	}
56	
57	export function loadFixtures(target: string, splits: Split[]): (Fixture & { split: Split })[] {
58	  return splits.flatMap((split) => {
59	    const dir = fixturesDir(target, split);
60	    if (!existsSync(dir)) return [];
61	    return readdirSync(dir)
62	      .filter((f) => f.endsWith(".json"))
63	      .sort()
64	      .map((f) => ({
65	        ...FixtureSchema.parse(JSON.parse(readFileSync(join(dir, f), "utf8"))),
66	        split,
67	      }));
68	  });
69	}
70	
71	const lockPath = (target: string): string => join(targetDir(target), "fixtures.lock");
72	const policyPath = (target: string): string => join(targetDir(target), "policy.json");
73	
74	function currentHashes(target: string): z.infer<typeof LockSchema> {
75	  const fixtures: Record<string, string> = {};
76	  for (const split of ["dev", "holdout"] as const) {
77	    const dir = fixturesDir(target, split);
78	    if (!existsSync(dir)) continue;
79	    for (const f of readdirSync(dir)
80	      .filter((n) => n.endsWith(".json"))
81	      .sort()) {
82	      fixtures[`${split}/${f}`] = sha256(readFileSync(join(dir, f), "utf8"));
83	    }
84	  }
85	  return {
86	    policy: sha256(readFileSync(policyPath(target), "utf8")),
87	    fixtures,
88	    code: codeHashes(target),
89	  };
90	}
91	
92	function claudeFiles(dir: string): [string, string][] {
93	  if (!existsSync(dir)) return [];
94	  return (
95	    readdirSync(dir, { withFileTypes: true, recursive: true })
96	      // Hidden files (.DS_Store and the like) and local settings are machine-specific, not evaluator.
97	      .filter(
98	        (d) =>
99	          d.isFile() &&
100	          !d.name.startsWith(".") &&
101	          !d.name.endsWith(".log") &&
102	          d.name !== "settings.local.json",
103	      )
104	      .map((d): [string, string] => {
105	        const p = join(d.parentPath, d.name);
106	        return [`.claude/${p.slice(dir.length + 1)}`, p];
107	      })
108	  );
109	}
110	
111	function codeHashes(target: string): Record<string, string> {
112	  const harness = join(import.meta.dirname, "..");
113	  const files: [string, string][] = [
114	    ...readdirSync(targetDir(target))
115	      .filter((n) => n.endsWith(".ts"))
116	      .map((n): [string, string] => [`target/${n}`, join(targetDir(target), n)]),
117	    ...readdirSync(join(harness, "src"))
118	      .filter((n) => n.endsWith(".ts"))
119	      .map((n): [string, string] => [`harness/src/${n}`, join(harness, "src", n)]),
120	    ...readdirSync(join(harness, "hooks")).map((n): [string, string] => [
121	      `harness/hooks/${n}`,
122	      join(harness, "hooks", n),
123	    ]),
124	    ...readdirSync(harness)
125	      .filter((n) => n.endsWith(".sh"))
126	      .map((n): [string, string] => [`harness/${n}`, join(harness, n)]),
127	    ...(existsSync(join(targetDir(target), "rules.json"))
128	      ? [["target/rules.json", join(targetDir(target), "rules.json")] as [string, string]]
129	      : []),
130	    ...["package.json", "package-lock.json"]
131	      .map((n): [string, string] => [n, join(harness, "..", n)])
132	      .filter(([, p]) => existsSync(p)),
133	    ...claudeFiles(join(harness, "..", ".claude")),
134	  ];
135	  return Object.fromEntries(
136	    files
137	      .sort(([a], [b]) => a.localeCompare(b))
138	      .map(([k, p]) => [k, sha256(readFileSync(p, "utf8"))]),
139	  );
140	}
141	
142	export function writeLock(target: string): void {
143	  writeFileSync(lockPath(target), `${JSON.stringify(currentHashes(target), null, 2)}\n`);
144	}
145	
146	// Returns the list of mismatches; empty means the evaluator is intact.
147	export function checkLock(target: string): string[] {
148	  if (!existsSync(lockPath(target))) return ["fixtures.lock is missing"];
149	  const locked = LockSchema.parse(JSON.parse(readFileSync(lockPath(target), "utf8")));
150	  const now = currentHashes(target);
151	  const problems: string[] = [];
152	  if (locked.policy !== now.policy) problems.push("policy.json changed");
153	  if (locked.code === undefined) problems.push("lock has no code hashes (run relock)");
154	  for (const [f, h] of Object.entries(locked.code ?? {})) {
155	    if (now.code?.[f] !== h) problems.push(`${f} changed`);
156	  }
157	  for (const f of Object.keys(now.code ?? {})) {
158	    if (locked.code?.[f] === undefined) problems.push(`${f} not in lock`);
159	  }
160	  // In a builder sandbox the holdout folder does not exist at all; that is the point of it.
161	  const holdoutAbsent = !existsSync(fixturesDir(target, "holdout"));
162	  for (const [f, h] of Object.entries(locked.fixtures)) {
163	    if (holdoutAbsent && f.startsWith("holdout/")) continue;
164	    if (now.fixtures[f] === undefined) problems.push(`${f} missing`);
165	    else if (now.fixtures[f] !== h) problems.push(`${f} changed`);
166	  }
167	  for (const f of Object.keys(now.fixtures)) {
168	    if (locked.fixtures[f] === undefined) problems.push(`${f} not in lock`);
169	  }
170	  return problems;
171	}
