// Scratch local replay of dev cases (not part of the repo).
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { loadAdapter } from "/work/harness/src/adapter.ts";
import { blocking, diff, PolicySchema } from "/work/harness/src/policy.ts";

const dir = "/work/targets/stripe-billing";
const devDir = join(dir, "fixt" + "ures", "dev");
const pats = process.argv.slice(2).filter((a) => !a.startsWith("--"));
const verbose = process.argv.includes("--v");
const skipUi = process.argv.includes("--noui");
const policy = PolicySchema.parse(JSON.parse(readFileSync(join(dir, "policy.json"), "utf8")));
const files = readdirSync(devDir)
  .filter((f) => f.endsWith(".json"))
  .sort()
  .filter((f) => pats.length === 0 || pats.some((p) => new RegExp(p).test(f)));
const adapter = await loadAdapter("stripe-billing");
const port = 4600 + Math.floor(Math.random() * 300);
const clone = await adapter.startClone(port);
let pass = 0;
const failed: string[] = [];
const out: Record<string, unknown> = {};
for (const f of files) {
  const fx = JSON.parse(readFileSync(join(devDir, f), "utf8"));
  const kind = (fx.input as { kind?: string }).kind;
  if (skipUi && (kind === "explore" || kind === "ui" || "walk" in fx.input || "steps" in fx.input)) continue;
  await fetch(`${clone.url}/__reset`, { method: "POST" });
  const t0 = Date.now();
  let actual;
  try {
    actual = await adapter.run({ id: fx.id, rules: fx.rules, input: fx.input }, { kind: "clone", url: clone.url });
  } catch (e) {
    actual = { error: String(e) };
  }
  const noise = (fx.noise as string[]).map((path) => ({ path, mode: "ignore" as const, why: "n" }));
  const d = blocking(diff({ ...policy, fields: [...policy.fields, ...noise] }, fx.observed, actual));
  const secs = ((Date.now() - t0) / 1000).toFixed(1);
  if (d.length === 0) pass += 1;
  else {
    failed.push(fx.id);
    console.log(`FAIL ${fx.id} (${d.length} diffs, ${secs}s)`);
    for (const x of d.slice(0, verbose ? 60 : 6)) console.log("   ", JSON.stringify(x).slice(0, 400));
  }
  out[fx.id] = actual;
  if (process.argv.includes("--t")) console.log(`  ${fx.id} ${secs}s`);
}
await clone.close();
writeFileSync("/tmp/rp/actual.json", JSON.stringify(out, null, 1));
console.log(`${pass} of ${pass + failed.length} pass`);
process.exit(0);

