// Tabulate credit-line discount lists over dev cases.
import { readdirSync, readFileSync } from "node:fs";
const dir = "/work/targets/stripe-billing/fixt" + "ures/dev/";
const filt = process.argv[2] ? new RegExp(process.argv[2]) : null;
for (const f of readdirSync(dir).sort()) {
  if (filt && !filt.test(f)) continue;
  const fx = JSON.parse(readFileSync(dir + f, "utf8"));
  const i = fx.input;
  const p = fx.observed.preview;
  if (!p || !p.lines) continue;
  const coupons = i.coupons ?? (i.coupon ? [i.coupon] : []);
  const ch = i.change;
  const inv = p.discounts;
  const name = (id) => (inv.includes(id) ? `inv${inv.indexOf(id)}` : `x${id.slice(-4)}`);
  const lines = p.lines.data
    .filter((l) => l.parent?.subscription_item_details?.proration)
    .map((l) => `${l.amount}[${l.discount_amounts.map((d) => name(d.discount) + ":" + d.amount).join(",")}]${/\(with/.test(l.description) ? "W" : ""}`);
  const cs = coupons.map((c) => `${c.percent_off ?? "$" + c.amount_off}${c.duration[0]}`).join("+");
  const pd = ch.discount ? `${ch.discount.percent_off ?? "$" + ch.discount.amount_off}${ch.discount.duration[0]}` : "-";
  console.log(
    [f.replace(".json", ""), i.billing_mode[0], ch.proration_behavior ?? "def", `sub=${cs || "-"}`, `pass=${pd}`, `inv=${inv.length}`, lines.join(" ")].join("  "),
  );
}

