1	/**
2	 * Time on a test clock: renewals at the period end, payment attempts an hour later, retries of a
3	 * failed payment, the end of a subscription set to cancel, and cancelling now (LIF-*).
4	 */
5	import { allocate, creditLine, priceOf, recurringDescription, specOf, specsOf } from "./billing.ts";
6	import {
7	  get,
8	  mint,
9	  nowFor,
10	  type Clock,
11	  type Invoice,
12	  type Line,
13	  type State,
14	  type Subscription,
15	} from "./state.ts";
16	import { periodAt } from "./time.ts";
17	
18	const HOUR = 3600;
19	const DAY = 86400;
20	// Retries after a failed renewal payment, counted from the first attempt (LIF-06: three attempts
21	// within five days; the spacing in between is not pinned by the recordings).
22	const RETRIES = [3 * DAY, 5 * DAY];
23	
24	function failing(state: State, customer: string): boolean {
25	  const c = get(state.customers, customer);
26	  const pm = c?.default_payment_method
27	    ? get(state.payment_methods, c.default_payment_method)
28	    : undefined;
29	  return pm?.fails === true;
30	}
31	
32	export function invoiceTotal(inv: Invoice): number {
33	  const sub = inv.lines.reduce((a, l) => a + l.amount, 0);
34	  return sub - inv.total_discount_amounts.reduce((a, d) => a + d.amount, 0);
35	}
36	
37	// Pending invoice items (prorations) of a subscription, moved onto an invoice.
38	export function takePending(state: State, sub: Subscription, invoice: string): Line[] {
39	  const out: Line[] = [];
40	  for (const ii of Object.values(state.invoice_items)) {
41	    if (ii.subscription !== sub.id || ii.invoice !== null) continue;
42	    ii.invoice = invoice;
43	    out.push({ ...ii.line, id: mint(state, "il") });
44	  }
45	  return out;
46	}
47	
48	function renew(state: State, sub: Subscription): void {
49	  const start = sub.period_end;
50	  const interval = priceOf(state, sub.items[0]?.price ?? "").interval;
51	  const end = periodAt(sub.anchor, interval, start)[1];
52	  const id = mint(state, "in");
53	  const pending = takePending(state, sub, id);
54	  const lines: Line[] = sub.items.map((it) => {
55	    const p = priceOf(state, it.price);
56	    return {
57	      id: mint(state, "il"),
58	      amount: p.unit_amount * it.quantity,
59	      description: recurringDescription(state, it.price, it.quantity),
60	      period: { start, end },
61	      price: it.price,
62	      quantity: it.quantity,
63	      proration: false,
64	      discountable: true,
65	      discount_amounts: [],
66	      subscription_item: it.id,
67	      invoice_item: null,
68	      credited: null,
69	      unit_amount_decimal: String(p.unit_amount),
70	    };
71	  });
72	  const active = sub.discounts.filter((d) => {
73	    const s = specOf(state, d);
74	    return s !== undefined && !(s.once && get(state.discounts, d)?.used === true);
75	  });
76	  const specs = specsOf(state, active);
77	  const alloc = allocate(
78	    lines.map((l) => l.amount),
79	    specs,
80	  );
81	  lines.forEach((l, i) => {
82	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
83	  });
84	  for (const s of specs) {
85	    const d = get(state.discounts, s.id);
86	    if (d && s.once) d.used = true;
87	  }
88	  sub.items.forEach((it, i) => {
89	    const l = lines[i];
90	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
91	  });
92	  const all = [...pending, ...lines];
93	  const inv: Invoice = {
94	    id,
95	    customer: sub.customer,
96	    subscription: sub.id,
97	    lines: all,
98	    discounts: specs.map((s) => s.id),
99	    total_discount_amounts: specs.map((s, k) => ({
100	      discount: s.id,
101	      amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
102	    })),
103	    billing_reason: "subscription_cycle",
104	    status: "draft",
105	    created: start,
106	    period_start: sub.period_start,
107	    period_end: start,
108	    attempt_count: 0,
109	    amount_paid: 0,
110	    auto_advance: true,
111	    next_payment_attempt: start + HOUR,
112	    proration_date: null,
113	    retries: [],
114	  };
115	  state.invoices[id] = inv;
116	  sub.latest_invoice = id;
117	  sub.period_start = start;
118	  sub.period_end = end;
119	  if (sub.status === "trialing") sub.status = "active";
120	}
121	
122	function attempt(state: State, inv: Invoice, at: number): void {
123	  const sub = inv.subscription ? get(state.subscriptions, inv.subscription) : undefined;
124	  const due = Math.max(0, invoiceTotal(inv));
125	  if (due === 0) {
126	    inv.status = "paid";
127	    inv.next_payment_attempt = null;
128	    return;
129	  }
130	  inv.attempt_count += 1;
131	  if (!failing(state, inv.customer)) {
132	    inv.status = "paid";
133	    inv.amount_paid = due;
134	    inv.next_payment_attempt = null;
135	    if (sub?.status === "past_due") sub.status = "active";
136	    return;
137	  }
138	  inv.status = "open";
139	  if (inv.attempt_count === 1) inv.retries = RETRIES.map((d) => at + d);
140	  const next = inv.retries.shift();
141	  inv.next_payment_attempt = next ?? null;
142	  if (sub && sub.status !== "canceled") sub.status = "past_due";
143	}
144	
145	// Runs every event of the clock's customers up to `to`, in time order.
146	export function advanceClock(state: State, clock: Clock, to: number): void {
147	  const customers = new Set(
148	    Object.values(state.customers)
149	      .filter((c) => c.clock === clock.id)
150	      .map((c) => c.id),
151	  );
152	  for (let guard = 0; guard < 1000; guard += 1) {
153	    const events: { at: number; run: () => void }[] = [];
154	    const consider = (at: number, run: () => void): void => {
155	      if (at <= to) events.push({ at, run });
156	    };
157	    for (const sub of Object.values(state.subscriptions)) {
158	      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
159	      const cancelAt = sub.cancel_at;
160	      if (cancelAt !== null && cancelAt <= sub.period_end) {
161	        consider(cancelAt, () => {
162	          sub.status = "canceled";
163	          sub.ended_at = cancelAt;
164	        });
165	        continue;
166	      }
167	      consider(sub.period_end, () => {
168	        if (sub.cancel_at_period_end) {
169	          sub.status = "canceled";
170	          sub.ended_at = sub.period_end;
171	        } else {
172	          renew(state, sub);
173	        }
174	      });
175	    }
176	    for (const inv of Object.values(state.invoices)) {
177	      if (!customers.has(inv.customer)) continue;
178	      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
179	        const at = inv.next_payment_attempt;
180	        if (at !== null) {
181	          consider(at, () => {
182	            attempt(state, inv, at);
183	          });
184	        }
185	      }
186	    }
187	    // The earliest event first; ties keep discovery order (subscriptions before invoices).
188	    const chosen = events.reduce<{ at: number; run: () => void } | null>(
189	      (best, e) => (best === null || e.at < best.at ? e : best),
190	      null,
191	    );
192	    if (chosen === null) break;
193	    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
194	    chosen.run();
195	  }
196	  clock.frozen_time = to;
197	}
198	
199	export function cancelNow(
200	  state: State,
201	  sub: Subscription,
202	  prorate: boolean,
203	  invoiceNow: boolean,
204	): void {
205	  const now = nowFor(state, sub.customer);
206	  if (prorate && now < sub.period_end) {
207	    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
208	    if (invoiceNow) {
209	      const id = mint(state, "in");
210	      const pending = takePending(state, sub, id);
211	      const lines: Line[] = [
212	        ...pending,
213	        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
214	      ];
215	      state.invoices[id] = {
216	        id,
217	        customer: sub.customer,
218	        subscription: sub.id,
219	        lines,
220	        discounts: [],
221	        total_discount_amounts: [],
222	        billing_reason: "subscription_cycle",
223	        status: "draft",
224	        created: now,
225	        period_start: sub.period_start,
226	        period_end: now,
227	        attempt_count: 0,
228	        amount_paid: 0,
229	        auto_advance: false,
230	        next_payment_attempt: null,
231	        proration_date: null,
232	        retries: [],
233	      };
234	      sub.latest_invoice = id;
235	    } else {
236	      for (const l of credits) {
237	        const id = mint(state, "ii");
238	        state.invoice_items[id] = {
239	          id,
240	          customer: sub.customer,
241	          subscription: sub.id,
242	          line: { ...l, id: "", invoice_item: id },
243	          invoice: null,
244	        };
245	      }
246	    }
247	  }
248	  sub.status = "canceled";
249	  sub.ended_at = now;
250	  sub.canceled_at ??= now;
251	  sub.cancel_at_period_end = false;
252	  sub.cancel_at = null;
253	}
