      if (!(await el.isVisible()) || !(await el.isEnabled())) continue;
      const href = await el.getAttribute("href");
      if (href !== null && !href.startsWith("#") && new URL(href, page.url()).origin !== origin) continue;
      out.push({ role, name: name.replace(/\\(.)/g, "$1"), nth });
