const states = new Map<string, number>(); const screens: string[][] = [];
const queue: { path: Action[]; from: number | null }[] = [{ path: [], from: null }];
const T = Date.now(); let edges = 0;
for (let node = queue.shift(); node; node = queue.shift()) {
